string gp="Assets/Maps/Buildings/Textures/WeatheredRedBrick_01/SG_Brick_World.shadergraph";var sh=UnityEditor.AssetDatabase.LoadAssetAtPath<Shader>(gp);var mats=Resources.FindObjectsOfTypeAll<Material>().Where(m=>m.shader==sh).ToArray();var defaults=new Material(sh);try{return new{shader=sh?sh.name:"missing",materials=mats.Select(m=>new{name=m.name,path=UnityEditor.AssetDatabase.GetAssetPath(m),dirty=UnityEditor.EditorUtility.IsDirty(m)}).ToArray(),properties=Enumerable.Range(0,sh.GetPropertyCount()).Where(i=>sh.GetPropertyName(i).StartsWith("_Brick")).Select(i=>{var n=sh.GetPropertyName(i);var t=sh.GetPropertyType(i);return new{name=n,type=t.ToString(),value=t==UnityEngine.Rendering.ShaderPropertyType.Float||t==UnityEngine.Rendering.ShaderPropertyType.Range?defaults.GetFloat(n).ToString():null,texture=t==UnityEngine.Rendering.ShaderPropertyType.Texture?UnityEditor.AssetDatabase.GetAssetPath(defaults.GetTexture(n)):null};}).ToArray()};}finally{UnityEngine.Object.DestroyImmediate(defaults);}
